    for (int i = 0; s[i] != '\0'; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            st[top] = c;
            top++;
        } else {
            if (top == 0) {
                ok = false;
                break;
            }
            char o = st[top - 1];
            top--;
            if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) {
                ok = false;
                break;
            }
        }
    }
    if (top != 0) ok = false;
    if (ok) cout << "YES" << endl;
    else cout << "NO" << endl;
    return 0;
}

