#include <iostream>
using namespace std;

char g[20][20];
int d[20][20];
int qr[400], qc[400];

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; i++) cin >> g[i];
    int sr = 0, sc = 0, tr = 0, tc = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            d[i][j] = -1;
            if (g[i][j] == 'S') { sr = i; sc = j; }
            if (g[i][j] == 'T') { tr = i; tc = j; }
        }
    }
    int dr[4] = {1, -1, 0, 0};
    int dc[4] = {0, 0, 1, -1};
    int dau = 0, cuoi = 0;
    qr[cuoi] = sr; qc[cuoi] = sc; cuoi++;
    d[sr][sc] = 0;
    while (dau < cuoi) {
        int r = qr[dau], c = qc[dau];
        dau++;
        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr >= 0 && nr < n && nc >= 0 && nc < m && g[nr][nc] != '#' && d[nr][nc] == -1) {
                d[nr][nc] = d[r][c] + 1;
                qr[cuoi] = nr; qc[cuoi] = nc; cuoi++;
            }
        }
    }
    cout << d[tr][tc] << endl;
    return 0;
}

lessons.theory:
**Đồ thị** gồm các **đỉnh** và các **cạnh** nối giữa chúng — mô hình cho mạng bạn bè, bản đồ đường đi, mạng máy tính… Một **thành phần liên thông** là nhóm đỉnh mà từ một đỉnh bất kỳ có thể đi tới mọi đỉnh khác trong nhóm.

Với đồ thị nhỏ, biểu diễn bằng **ma trận kề**: `ke[u][v] = 1` nếu có cạnh nối u và v.

**Duyệt theo chiều sâu** (Depth-First Search – DFS) đi "sâu nhất có thể" theo một hướng rồi mới quay lui:

```cpp
int n;
int ke[55][55];
bool tham[55];

void dfs(int u) {
    tham[u] = true;
    for (int v = 1; v <= n; v++) {
        if (ke[u][v] == 1 && !tham[v]) {
            dfs(v);
        }
    }
}
```

**Đếm thành phần liên thông:** duyệt lần lượt các đỉnh; mỗi khi gặp một đỉnh **chưa thăm**, ta đã phát hiện một thành phần mới → tăng bộ đếm và gọi `dfs` để đánh dấu toàn bộ thành phần đó.

```cpp
int soTP = 0;
for (int u = 1; u <= n; u++) {
    if (!tham[u]) {
        soTP++;
        dfs(u);
    }
}
```

Để biết **kích thước** của từng thành phần, có thể dùng một biến toàn cục `dem` tăng thêm 1 mỗi khi `dfs` thăm một đỉnh.

Nhớ khởi tạo ma trận kề bằng 0 trước khi đọc cạnh, và vì đồ thị **vô hướng** nên mỗi cạnh u–v phải gán cả `ke[u][v]` và `ke[v][u]`. Với ma trận kề, DFS có độ phức tạp O(n²).

