#include <iostream>
using namespace std;

int n, m;
int ke[55][55];
bool tham[55];
int dem = 0;

void dfs(int u) {
    tham[u] = true;
    dem++;
    for (int v = 1; v <= n; v++) {
        if (ke[u][v] == 1 && !tham[v]) dfs(v);
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i <= n; i++) {
        tham[i] = false;
        for (int j = 0; j <= n; j++) ke[i][j] = 0;
    }
    for (int k = 0; k < m; k++) {
        int u, v;
        cin >> u >> v;
        ke[u][v] = 1;
        ke[v][u] = 1;
    }
    int soTP = 0, lonNhat = 0;
    for (int u = 1; u <= n; u++) {
        if (!tham[u]) {
            soTP++;
            dem = 0;
            dfs(u);
            if (dem > lonNhat) lonNhat = dem;
        }
    }
    cout << soTP << endl;
    cout << lonNhat << endl;
    return 0;
}
